def _fit(times, state, strain, rate):
    from scipy.optimize import least_squares
    n, k = strain.shape
    target = np.r_[strain.ravel(), rate]
    active = np.r_[np.ones(7, dtype=bool), [np.any(v) for v in state[-2:]]]

    def build(taus):
        a, b = _design(taus, times, state)
        return np.concatenate((a.reshape(n * k, 9), b))[:, active]
    lower, upper = (0.2, 8.0)
    p_min = np.r_[lower, 1e-06, np.full(active.sum(), -np.inf)]
    p_max = np.r_[upper - 1e-06, 1.0, np.full(active.sum(), np.inf)]

    def taus(q):
        return np.array([q[0], q[0] + (upper - q[0]) * q[1]])

    def optimize(start, scales, loss):

        def residual(q):
            return (np.einsum('ij,j->i', build(taus(q)), q[2:]) - target) / scales
        return least_squares(residual, start, bounds=(p_min, p_max), loss=loss, x_scale='jac', max_nfev=160)
    pilots = []
    for a, b in ((0.35, 1.3), (0.65, 3.0), (1.15, 5.4)):
        w = np.linalg.lstsq(build([a, b]), target, rcond=None)[0]
        pilots.append(optimize(np.r_[a, (b - a) / (upper - a), w], 0.05, 'soft_l1'))
    pilot = min(pilots, key=lambda fit: fit.cost)
    raw = 0.05 * pilot.fun

    def mad(v):
        return max(1e-06, 1.4826 * np.median(np.abs(v - np.median(v))))
    scales = np.r_[np.full(n * k, mad(raw[:n * k])), np.full(n, mad(raw[n * k:]))]
    fit = optimize(pilot.x, 2.385 * scales, 'cauchy')
    weights = np.zeros(9)
    weights[active] = fit.x[2:]
    return (taus(fit.x), weights)

def _fit_seed(dt, times, hist, hold, aligned, initial, curves, rate):
    from scipy.optimize import least_squares
    n, k = curves.shape
    target = np.r_[curves.ravel(), rate]

    def build(taus):
        a, b = _design(taus, dt, times, hist, hold, aligned, initial)
        return np.vstack((a.reshape(-1, 7), b))

    def unpack(p):
        return (np.array([p[0], p[0] + p[1] * (8.0 - p[0])]), p[2:])
    lo = np.r_[0.2, 1e-05, np.full(7, -np.inf)]
    hi = np.r_[8.0 - 1e-05, 1.0, np.full(7, np.inf)]

    def optimize(p, scales, loss):

        def fun(q):
            t, w = unpack(q)
            return (np.einsum('ij,j->i', build(t), w) - target) / scales
        return least_squares(fun, p, bounds=(lo, hi), loss=loss, x_scale='jac', max_nfev=160)
    pilots = []
    for a, b in ((0.35, 1.3), (0.6, 3.0), (1.15, 5.4)):
        m = build(np.array([a, b]))
        w = np.linalg.lstsq(m, target, rcond=None)[0]
        pilots.append(optimize(np.r_[a, (b - a) / (8.0 - a), w], 0.05, 'soft_l1'))
    pilot = min(pilots, key=lambda o: o.cost)
    raw = pilot.fun * 0.05

    def mad(r):
        return max(1e-06, 1.4826 * np.median(np.abs(r - np.median(r))))
    scales = np.r_[np.full(n * k, mad(raw[:n * k])), np.full(n, mad(raw[n * k:]))]
    fit = optimize(pilot.x, 2.385 * scales, 'cauchy')
    return unpack(fit.x)
